/** Where an agent runs, as opposed to what it does. */
export type RuntimeEnv = 'cloud' | 'local';

/** A platform a mode declares it runs on: a released GOOS, or wasm. */
export type Platform = 'darwin' | 'esp32' | 'linux' | 'windows';

/** Every mode key the catalog declares.
 *
 *  Use it for tables that must cover every mode. Do NOT use it for a value
 *  that came off the wire or out of the database — `modeMeta` takes a plain
 *  string on purpose, because a stored record can outlive its mode. */
export type ModeKey = 'access' | 'armory' | 'codebase_analysis' | 'dmarc_reports' | 'docs_sync' | 'editor' | 'github' | 'github_work' | 'language' | 'mailer' | 'model_steward' | 'momus' | 'package_scan' | 'posture' | 'preview' | 'printer' | 'relay' | 'rss' | 'scada' | 'shard_coordinator' | 'shard_store';

/** One agent mode's UI metadata. Glyph SVGs are NOT here — they are
 *  hand-authored in icons/mode-tool-icons.ts and looked up by key. */
export interface ModeMeta {
	key: ModeKey;
	label: string;
	desc: string;
	about: string;
	color: string;
	/** Option name in MODE_GLYPHS for this mode; '' when none is drawn yet. */
	glyph: string;
	/** Entitlement pool this mode draws from. 'other' is 0 on the free tier. */
	bucket: 'github' | 'language' | 'proxy' | 'notify' | 'browser' | 'editor' | 'other';
	/** Tool types this mode's agent requires but does not construct itself. */
	tools: string[];
	/** Operating systems this mode can run on. */
	platforms: Platform[];
	/** Where this mode may be placed. */
	runtimeEnvs: RuntimeEnv[];
	/** False when the mode is declared but the build has no factory for it —
	 *  it can be shown, but it cannot be deployed. */
	registered: boolean;
}

