export const MODE_KEYS: ModeKey[] = MODES.map((m) => m.key);

const BY_KEY = new Map<string, ModeMeta>(MODES.map((m) => [m.key, m]));

/** The catalog entry for a wire value, or undefined for a mode this build
 *  does not know — a stored record can outlive the mode that wrote it. */
export function modeMeta(key: string): ModeMeta | undefined {
	return BY_KEY.get(key);
}

/** Where a mode may run. Unknown modes get an EMPTY list, not a permissive
 *  one: a mode nothing declares must not be offered anywhere. */
export function runtimeEnvsFor(key: string): RuntimeEnv[] {
	return BY_KEY.get(key)?.runtimeEnvs ?? [];
}

/** Operating systems a mode supports. Empty for an unknown mode, same reason. */
export function platformsFor(key: string): Platform[] {
	return BY_KEY.get(key)?.platforms ?? [];
}
